#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="C:\Users\unico\Documents\Estuary\estuary-product\estuary-ts-sdk\node_modules\esbuild\node_modules;C:\Users\unico\Documents\Estuary\estuary-product\estuary-ts-sdk\node_modules;C:\Users\unico\Documents\Estuary\estuary-product\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/c/Users/unico/Documents/Estuary/estuary-product/estuary-ts-sdk/node_modules/esbuild/node_modules:/mnt/c/Users/unico/Documents/Estuary/estuary-product/estuary-ts-sdk/node_modules:/mnt/c/Users/unico/Documents/Estuary/estuary-product/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

# Support pipeline input
if ($MyInvocation.ExpectingInput) {
  $input | & "$basedir/../esbuild/bin/esbuild"   $args
} else {
  & "$basedir/../esbuild/bin/esbuild"   $args
}
$env:NODE_PATH=$env_node_path
exit $LASTEXITCODE
